CREATE TABLE network_participants(id text PRIMARY KEY,name text NOT NULL,country text NOT NULL,role text NOT NULL CHECK(role IN ('origin','settlement','destination')),asset text NOT NULL,provider_binding text NOT NULL,enabled boolean NOT NULL DEFAULT true,mode text NOT NULL CHECK(mode='sandbox'),external_validated boolean NOT NULL DEFAULT false CHECK(external_validated=false));
INSERT INTO network_participants VALUES('nigeria-sandbox','Nigeria sandbox participant','NG','origin','NGN','sim:nigeria:v1',true,'sandbox',false),('settlement-sandbox','KUSD settlement simulator','SIM','settlement','KUSD','sim:kusd:v1',true,'sandbox',false),('nigeria-payout-sandbox','Nigeria sandbox payout participant','NG','destination','NGN','sim:nigeria-payout:v1',true,'sandbox',false),('kenya-sandbox','Kenya sandbox participant — pending selection','KE','destination','KES','sim:kenya:v1',false,'sandbox',false);
CREATE TABLE network_corridors(id text PRIMARY KEY,source_asset text NOT NULL,destination_asset text NOT NULL,origin_id text NOT NULL REFERENCES network_participants,settlement_id text NOT NULL REFERENCES network_participants,destination_id text NOT NULL REFERENCES network_participants,enabled boolean NOT NULL DEFAULT true,capacity_minor numeric(30,0) NOT NULL CHECK(capacity_minor>0),mode text NOT NULL CHECK(mode='sandbox'));
INSERT INTO network_corridors VALUES('ng-ng-sandbox','NGN','NGN','nigeria-sandbox','settlement-sandbox','nigeria-payout-sandbox',true,100000000,'sandbox'),('ng-ke-sandbox','NGN','KES','nigeria-sandbox','settlement-sandbox','kenya-sandbox',false,100000000,'sandbox');
CREATE TABLE network_plans(id text PRIMARY KEY,merchant_id text NOT NULL REFERENCES merchants,quote_id text NOT NULL UNIQUE REFERENCES quotes,corridor_id text NOT NULL REFERENCES network_corridors,scenario text NOT NULL CHECK(scenario IN ('success','timeout','insufficient_float')),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,merchant_id));
CREATE TRIGGER immutable_network_plans BEFORE UPDATE OR DELETE ON network_plans FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE TABLE network_reservations(plan_id text PRIMARY KEY REFERENCES network_plans,intent_id text NOT NULL UNIQUE REFERENCES intents,corridor_id text NOT NULL REFERENCES network_corridors,amount_minor numeric(30,0) NOT NULL CHECK(amount_minor>0),state text NOT NULL CHECK(state IN ('held','consumed','released')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION guarded_network_reservation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.plan_id,NEW.intent_id,NEW.corridor_id,NEW.amount_minor,NEW.created_at) IS DISTINCT FROM (OLD.plan_id,OLD.intent_id,OLD.corridor_id,OLD.amount_minor,OLD.created_at) OR OLD.state<>'held' OR NEW.state NOT IN ('consumed','released') THEN RAISE EXCEPTION 'Corridor reservation is immutable or terminal'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guarded_network_reservation BEFORE UPDATE ON network_reservations FOR EACH ROW EXECUTE FUNCTION guarded_network_reservation();
CREATE TRIGGER no_delete_network_reservations BEFORE DELETE ON network_reservations FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE TABLE network_legs(id text PRIMARY KEY,plan_id text NOT NULL REFERENCES network_plans,position integer NOT NULL CHECK(position BETWEEN 1 AND 3),instruction_id text NOT NULL REFERENCES instructions,participant_id text NOT NULL REFERENCES network_participants,provider_binding text NOT NULL,request jsonb NOT NULL,state text NOT NULL CHECK(state IN ('prepared','unknown','confirmed','rejected')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(plan_id,position));
CREATE FUNCTION guarded_network_leg() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.id,NEW.plan_id,NEW.position,NEW.instruction_id,NEW.participant_id,NEW.provider_binding,NEW.request,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.plan_id,OLD.position,OLD.instruction_id,OLD.participant_id,OLD.provider_binding,OLD.request,OLD.created_at) OR (NEW.state<>OLD.state AND NOT (OLD.state IN ('prepared','unknown') AND NEW.state IN ('unknown','confirmed','rejected'))) THEN RAISE EXCEPTION 'Corridor leg instruction is immutable or terminal'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guarded_network_leg BEFORE UPDATE ON network_legs FOR EACH ROW EXECUTE FUNCTION guarded_network_leg();
CREATE TRIGGER no_delete_network_legs BEFORE DELETE ON network_legs FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE TABLE network_movements(leg_id text PRIMARY KEY REFERENCES network_legs,provider_reference text NOT NULL UNIQUE,fingerprint text NOT NULL,outcome text NOT NULL CHECK(outcome IN ('confirmed','rejected')),payload jsonb NOT NULL,journal_id text REFERENCES journals,created_at timestamptz NOT NULL DEFAULT now(),CHECK((outcome='confirmed')=(journal_id IS NOT NULL)));
CREATE TRIGGER immutable_network_movements BEFORE UPDATE OR DELETE ON network_movements FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE INDEX network_capacity ON network_reservations(corridor_id,state);

ALTER TABLE quotes DROP CONSTRAINT quote_assets;
ALTER TABLE quotes ADD CONSTRAINT quote_assets CHECK(
 (provider='kora-sandbox' AND source_asset IN ('NGN','KES','GHS','USDC') AND destination_asset IN ('NGN','KES','GHS','USDC') AND (source_asset<>destination_asset OR (source_asset='NGN' AND destination_asset='NGN'))) OR
 (provider='paystack-test' AND source_asset='NGN' AND destination_asset='NGN') OR
 (provider='stellar-testnet' AND source_asset='NGN' AND destination_asset='KUSD')
);
